import { renderHook } from '@testing-library/react-hooks';

import { useShouldMoveOut } from './useShouldMoveOut';

describe('useShouldMoveOut', () => {
    const onBack = jest.fn();

    beforeEach(() => {
        onBack.mockClear();
    });

    it('waits for the elements to finish loading before checking the active ID', () => {
        const { rerender } = renderHook(
            ({ elementID, elementIDs, loadingElements }) =>
                useShouldMoveOut({ elementID, elementIDs, loadingElements, onBack }),
            { initialProps: { elementID: 'removed', elementIDs: ['available'], loadingElements: true } }
        );

        expect(onBack).not.toHaveBeenCalled();

        rerender({ elementID: 'removed', elementIDs: ['available'], loadingElements: false });
        expect(onBack).toHaveBeenCalledTimes(1);
    });

    it('keeps the view open while its ID remains in the elements list', () => {
        const { rerender } = renderHook(
            ({ elementIDs }) =>
                useShouldMoveOut({ elementID: 'active', elementIDs, loadingElements: false, onBack }),
            { initialProps: { elementIDs: ['active', 'other'] } }
        );

        rerender({ elementIDs: ['other', 'active'] });
        expect(onBack).not.toHaveBeenCalled();

        rerender({ elementIDs: ['other'] });
        expect(onBack).toHaveBeenCalledTimes(1);
    });

    it.each([
        ['undefined ID', undefined, ['available']],
        ['empty ID', '', ['available']],
        ['empty list', 'active', []],
    ])('moves out for an %s', (_, elementID, elementIDs) => {
        renderHook(() => useShouldMoveOut({ elementID, elementIDs, loadingElements: false, onBack }));
        expect(onBack).toHaveBeenCalledTimes(1);
    });
});
